pseudocode:
1. let stack = [], num = 0, op = '+';
2. for (let i = 0; i < s.length; i++) {
3.   if (isDigit(s[i])) num = num * 10 + parseInt(s[i]);
4.   if (!isDigit(s[i]) && s[i] !== ' ' || i === s.length - 1) {
5.     if (op === '+') stack.push(num);
6.     else if (op === '-') stack.push(-num);
7.     else if (op === '*') stack.push(stack.pop() * num);
8.     else if (op === '/') stack.push(Math.trunc(stack.pop() / num));
9.     op = s[i]; num = 0;
10.  }
11. }
12. return stack.reduce((a, b) => a + b, 0);
